Lemma cells_size_map_C8 : forall l : list word, cells_size (map C8 l) = (8 * length l)%nat.
Proof. induction l as [|x l IH]; [reflexivity|]. cbn [map cells_size csize length]. rewrite IH. lia. Qed.

