Lemma rs_put_round : forall (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 ->
  rs_at_put H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf ->
  hs_SR H (fun cf' => rs_done H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 cf'
                      \/ exists w', zlength (w_sds w') = zlength (w_sds w)
